import sys

def parse_time(time_str):
    parts = time_str.split()
    hh_mm = parts[0]
    period = parts[1]
    hh, mm = map(int, hh_mm.split(':'))

    if period == 'AM':
        if hh == 12:
            hh = 0
    else:  # PM
        if hh != 12:
            hh += 12

    return hh * 60 + mm

def solve():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        t_line = next(iterator).strip()
        while not t_line:
            t_line = next(iterator).strip()
        T = int(t_line)
    except StopIteration:
        return

    for _ in range(T):
        try:
            p_line = next(iterator).strip()
            while not p_line:
                p_line = next(iterator).strip()

            n_line = next(iterator).strip()
            while not n_line:
                n_line = next(iterator).strip()
            N = int(n_line)

            P = parse_time(p_line)
            result = []

            for _ in range(N):
                lr_line = next(iterator).strip()
                while not lr_line:
                    lr_line = next(iterator).strip()

                # Parse L and R from the line
                # Format: "HH:MM AM HH:MM AM"
                # We need to split carefully because there are spaces within times
                # The structure is fixed: Time1 (2 parts) Time2 (2 parts)
                tokens = lr_line.split()
                # tokens should be [HH:MM, AM/PM, HH:MM, AM/PM]
                L_str = tokens[0] + " " + tokens[1]
                R_str = tokens[2] + " " + tokens[3]

                L = parse_time(L_str)
                R = parse_time(R_str)

                if L <= P <= R:
                    result.append('1')
                else:
                    result.append('0')

            print("".join(result))

        except StopIteration:
            break

if __name__ == "__main__":
    solve()
